          body:'<b>社会资本</b>是人与人之间有来有往的信任与互助。志愿服务把素不相识的人临时编织进一张关怀的网——托管班里的陪伴、车站里的指引，都是在用行动积累社会的信任存量。当“奉献、友爱、互助、进步”成为风尚，城市的韧性也就厚了起来。',
          aha:'一座城市靠不靠得住，看危难时有多少陌生人愿意伸手。'
