        {t:'政策发力', x:'十大重点行业稳增长方案推进，“人工智能+制造”专项行动实施意见发布。'},
        {t:'底盘稳固', x:'上半年一二三产齐头并进，实体经济巩固壮大，产业体系韧性增强。'}
