          body:'<b>宏观经济学</b>里，产业体系是经济韧性的底盘。当外部冲击与内部转型叠加，完整的产业体系意味着关键时候“不掉链子”。把实体经济根基筑牢，经济增长才不只是账面数字，而是能扛风险的真实能力。',
