          lens:'工作社会学', lensId:'work',
          body:'<b>工作社会学</b>把招聘环节看作权力不对等的筛选现场。把妊娠测试塞进入职体检，等于在录用前就给育龄女性贴上了"潜在风险"的标签，把生育这一社会再生产职能，悄悄折算成了女性的就业劣势。北大研究团队基于中国家庭追踪调查（CFPS）发现，女性生育后七年内个人收入平均下降21.4%、就业率降14.1%——"母职惩罚"早已前移成了入职环节的"生育预期歧视"。',
          aha:'查的不是怀孕，是她未来会不会"添麻烦"。',
          research: {
            title:'Gender norms and the child penalty in China',
            authors:'Zhang M., Wang Y., Hou L.',
            year:2024,
            venue:'Journal of Economic Behavior & Organization 221:277–291',
            url:'https://doi.org/10.1016/j.jebo.2024.03.011',
            summary:'基于中国家庭追踪调查（CFPS）数据，研究发现女性生育后七年内个人收入平均下降21.4%、就业率降14.1%、工时降17.9%；若本人或配偶持传统性别观念，惩罚更重（约35%—40%），解释了企业为何倾向在入职环节就规避育龄女性。',
            fromNode:'work'
          }
