          lens:'法律社会学', lensId:'law',
          body:'<b>法律社会学</b>提醒我们，纸面禁令要落地，靠的是被发现的概率与违法成本。当就业歧视隐蔽、举证困难、单次罚款仅2.2万，对部分企业而言违规仍是"划算"的——真正能拦住行为的，不是条文本身，而是让每一次试探都付出足够代价的执行密度。',
          aha:'法律写进纸里不难，难的是让每一次违规都疼。'
