      id: 8,
      title: '中国烹协废止“大师”“名师”等称号：历年评定证书、服装即刻失效',
      source: '腾讯新闻',
      url: 'https://new.qq.com/rain/a/20260803A0261Y00?refer=cp_1009',
      kicker: '文化 · 社会学 / 文化',
      gist: '中国烹饪协会接连公告，明确历年由协会评定、颁发的“中国烹饪大师（名师）”“中国餐饮服务大师（名师）”等各类含“大师”“名师”的称号、证书、服装即刻失效，并撤销“之乡、之都、美食地标城市”等全部相关称号。',
      thread: [
        {t:'公告出台', x:'中国烹饪协会发布公告，历年评定的“大师/名师”类称号、证书、服装即刻失效，同时撤销“之乡、之都、美食地标城市”等称号。'},
        {t:'背景', x:'该公告早在7月23日已发布，8月初被多家媒体集中报道，引发行业与公众讨论。'},
        {t:'行业反响', x:'业内认为，清理“大师”称谓有助于刹住借称号搞培训收费、加盟背书等乱象，推动评价回归技能本身。'}
      ],
      interpretations: [
        {
          q:'为什么一个行业协会，说废就废掉自己发了多年的“大师”称号？',
          naive:'以为“大师”只是个荣誉头衔。',
          lens:'制度主义', lensId:'institutionalism',
          body:'<b>制度主义</b>视角下，行业协会的称号是一套“认证制度”，本应传递质量信号。但当“大师/名师”被批量授予、又常被用来给培训费、加盟费背书，称号就异化为寻租符号。主动废止，是制度自我纠偏——把权威性从“头衔”收回到“标准与考核”本身。',
          aha:'真正值钱的不是“大师”两个字，而是背后那套谁都糊弄不了的标准。'
        },
        {
          q:'为什么我们这么容易被“大师”“名师”这类词打动？',
          naive:'以为看的是真实水平。',
          lens:'文化资本', lensId:'cultural_capital',
          body:'<b>文化资本</b>指被社会认可、可转化为声望与资源的符号。在餐饮这类“手艺即信任”的行业，“大师”就是把技艺包装成文化资本的话术；当人人皆“大师”，符号通胀、信任蒸发，消费者反而更无从判断。废止称号，某种程度上是给被玩坏的文化资本“挤水分”。',
          aha:'头衔一旦人人都有，它就不再是资本，只是一张人人都有的贴纸。'
        }
      ],
      theories: [
        {id:'institutionalism', label:'制度主义'},
        {id:'cultural_capital', label:'文化资本'}
      ],
      essayTopics: [{"id":"inherit_innovate","label":"守正创新"},{"id":"tradition_activate","label":"传统文化活化"},{"id":"persist_flex","label":"坚守与变通"},{"id":"fairness","label":"公平正义"}],
      review: {strength:'strong', disciplines:['soc']}
