      id: 1,
      title: '国务院拟修改住房公积金管理条例：灵活就业人员可自缴，装修物业费也能提',
      source: '央视网',
      url: 'https://news.cctv.cn/2026/08/02/ARTIcuPyJtEjrr5rs0jE24aO260802.shtml',
      kicker: '民生 · 经济学 / 社会学',
