        {t:'覆盖扩容', x:'个体工商户、非全日制及灵活就业人员可自愿参加；外卖员、快递员、网约车司机等新业态从业者今后可自缴公积金。'},
        {t:'用途拓宽', x:'自住住房装修、支付物业费纳入可提取情形；多地已推适老化改造、加装电梯等创新提取。'}
