          naive:'以为全国一把尺子改到底。',
          lens:'社会分层', lensId:'stratification',
          body:'<b>社会分层</b>视角提醒我们，住房压力在不同城市、不同阶层之间高度不均。一二线总价高，改革主推提高贷款额度；其余城市则侧重拓宽提取范围、细化城市更新用途。这种“因城施策”正是承认：住房焦虑的分布本身是分层的，政策要对症，就不能用单一标准覆盖所有群体。',
          aha:'同一种“住房难”，在不同城市长着不同的样子，政策也得长成不同的样子。'
