          body:'<b>工作社会学</b>关注劳动过程中的身体与权利处境。超龄劳动者的体能和恢复能力与年轻人不同，强制或常态加班对他们风险更高；规定“一般不安排加班”，是把年龄差异纳入了劳动保护的考量，而非用一套均质标准对待所有劳动者。',
          aha:'真正的平等，是看见差异之后仍给予恰当的保护。'
