          lens:'风险社会理论', lensId:'risk_society',
          body:'<b>贝克的风险社会理论</b>指出，现代风险越来越具有“人为的、系统性的、跨地域的”特征。极端高温背后是气候系统的失衡，它冲击电力、城市运维、农业与劳动安全，单靠个人“忍耐热”无法应对。各地的错峰施工、纳凉网络，正是把气候风险纳入公共治理的尝试。',
