      kicker: '通信 · 社会学 / 经济',
      gist: '7月31日晚，中国电信、移动、联通同步公告：8月1日起互联网渠道订购号卡仅限官方App、官网，第三方平台全面停办；官方称是为整治虚假售卡与信息泄露，“19元200G”等低价大流量卡随之退场——一道渠道收紧，牵动的是信息安全、市场竞争与用户资费的多重博弈。',
