          lens:'垄断', lensId:'econ_monopoly',
          body:'<b>垄断与平台权力</b>视角下，第三方渠道曾是运营商争夺新增用户、尤其是下沉市场的“价格战”前线，低价卡靠渠道补贴存活。当官方收口渠道、统一入口，价格发现机制收紧，低价供给自然退潮——渠道集中度上升，用户议价空间反而被压缩。',
