      id: 12,
      title: '中青报调查：82.2%受访大学生暑期打工或有计划，积累经验超赚钱居首',
      source: '中国青年报 / 中青网',
      url: 'https://news.cyol.com/gb/shipin/articles/2026-07/30/content_lbnzLoUB42.html',
