        {t:'红线清单', x:'设22项禁止行为，医药代表不得承担销售任务、不得统计处方、不得输送财物；持有人不得聘用有商业贿赂记录者。'},
        {t:'联动惩戒', x:'药监、卫健、医保等七部门信息共享、行刑衔接，对违规者联合惩戒，行贿相关药品可面临信用评价与限制挂网。'}
