          lens:'媒介社会学', lensId:'media',
          body:'<b>媒介社会学</b>看到，在注意力经济里，“悬念”本身就是流量：原始画面缺失、身份不明，恰好给AI生成、特效剪辑留下巨大讨论空间，评论区自然分裂成立场阵营。视频不需要被证实，只要足够“超出认知”，就能完成从猎奇到转发的裂变。',
          aha:'让人转发的，往往不是真相，而是“这怎么会真”的惊诧。'
