          lens:'情绪与动机', lensId:'psy_emotion',
          body:'<b>情绪与动机</b>视角下，这类视觉奇观先触发的是“敬畏/惊叹”这样的情绪本能，而非理性核验。认知失调——“这超出我对人体的全部经验”——会转化为强烈的分享冲动。情绪跑在事实前面，是社交媒体时代刷屏的底层动力。',
