          lens:'媒介社会学', lensId:'media',
          body:'<b>媒介社会学</b>关注“情绪价值”如何被包装成可售卖的注意力商品：短视频账号用年轻女性形象、暧昧文案引流，把正常漂流异化为“商务漂流”式暗示。当流量逻辑压倒内容底线，擦边就成了低成本获客的试探——媒介放大了人性的猎奇，也放大了越界。',
